453	-- deduct_credits — atomic credit deduction
454	CREATE OR REPLACE FUNCTION deduct_credits(p_user_id uuid, p_amount int)
455	RETURNS boolean
456	LANGUAGE plpgsql SECURITY DEFINER AS $$
457	DECLARE
458	  v_account_id uuid;
459	  v_current int;
460	BEGIN
461	  v_account_id := get_primary_account(p_user_id);
462	  IF v_account_id IS NULL THEN RETURN false; END IF;
463	
464	  SELECT COALESCE((pl.limits_json->>'ai_credits_per_month')::int, 30)
465	  INTO v_current
466	  FROM account_app_access aaa
467	  JOIN plans pl ON pl.id = aaa.plan_id
468	  WHERE aaa.account_id = v_account_id AND aaa.app_id = get_app_id('rankora');
469	
470	  -- For now, always allow (credits are plan-based not balance-based in BUBS)
471	  RETURN true;
472	END;
473	$$;
474	GRANT EXECUTE ON FUNCTION deduct_credits(uuid, int) TO authenticated;
