486	-- is_job_owner — check if user owns the job
487	CREATE OR REPLACE FUNCTION is_job_owner(p_job_id uuid, p_user_id uuid)
488	RETURNS boolean
489	LANGUAGE sql STABLE SECURITY DEFINER AS $$
490	  SELECT EXISTS (
491	    SELECT 1 FROM rankora_jobs rj
